// -----------------------------------------------------------------------------------------------------------------
// 90201 Contagion - hands the enemy version of every plague carried to the pack, refreshes the carrier's own
// -----------------------------------------------------------------------------------------------------------------

class PestifereContagionSpellScript : public SpellScript
{
    PrepareSpellScript(PestifereContagionSpellScript);

    void HandleAfterCast()
    {
        Player* caster = GetPestifere(GetCaster());
        if (!caster || !CarriesAnyPlague(caster))
            return;

        SpellInfo const* spellInfo = GetSpellInfo();
        ObjectGuid const casterGuid = caster->GetGUID();

        // The spell's own area radius (effect 2, cloned from Pestilence: 10 yd). CalcRadius applies the caster's
        // radius modifiers, which is how the Miasme talent widens it; a fixed radius here would ignore them.
        float const radius = spellInfo->Effects[EFFECT_2].CalcRadius(caster);
        std::list<Unit*> const enemies = GetEnemiesInRange(caster, radius);
        uint32 applied = 0;
        uint32 refused = 0;

        for (Unit* enemy : enemies)
        {
            SpreadResult const spread = SpreadPlagues(caster, enemy);
            applied += spread.applied;
            refused += spread.refused;

            // Contagion also keeps the rot already on the pack alive, so a pack held long enough ripens
            if (Aura* rot = enemy->GetAura(SPELL_POURRITURE, casterGuid))
                rot->RefreshDuration();

            if (!spread.applied)
                continue;

            caster->SetInCombatWith(enemy);
            enemy->AddThreat(caster, CONTAGION_THREAT_PER_PLAGUE * float(spread.applied), SPELL_SCHOOL_MASK_NORMAL,
                spellInfo);
        }

        // Feeding the pack feeds the carrier: plagues never time out while Contagion keeps landing. Sépulcre's
        // plague is not refreshed: that would only stretch the damage it owes.
        for (Plague const& plague : Plagues)
            if (Aura* carried = caster->GetAura(plague.selfSpellId, casterGuid))
                carried->RefreshDuration();

        // How far a cast actually reached: the evidence for tuning the radius. Refused means an enemy in range
        // that did not take a plague (an immunity, or an aura the core would not apply).
        LOG_INFO("module", "Pestifere: {} cast Contagion ({:.1f} yd, Virulence {}): {} enemies in range, {} plagues "
            "applied, {} refused", caster->GetName(), radius, GetVirulence(caster), enemies.size(), applied, refused);
    }

    void Register() override
    {
        AfterCast += SpellCastFn(PestifereContagionSpellScript::HandleAfterCast);
    }
};

